<?php declare(strict_types=1); namespace Annam; $title='WhatsApp inbox'; ?>
<p><a class="o-btn" href="/manage/whatsapp/settings/">Connection settings</a></p><div class="php-inbox"><aside class="o-card"><?php foreach($conversations as $chat): ?><a class="php-chat <?= ($conversation['id']??null)===$chat['id']?'on':'' ?>" href="/manage/whatsapp/<?= e($chat['id']) ?>/"><strong><?= e($chat['display_name']?:$chat['phone']) ?></strong><?php if($chat['unread_count']): ?><b><?= e($chat['unread_count']) ?></b><?php endif; ?><small><?= e($chat['preview']) ?></small></a><?php endforeach; ?><?php if(!$conversations): ?><p>No conversations yet.</p><?php endif; ?></aside><section class="o-card"><?php if($conversation): ?><h2><?= e($conversation['display_name']?:$conversation['phone']) ?></h2><p><?= e($conversation['phone']) ?></p><div class="o-actions"><a class="o-btn" href="/manage/orders/new/?conversation=<?= e($conversation['id']) ?>">Create booking</a><form method="post" action="read/"><?= csrf() ?><button class="o-btn">Mark as read</button></form></div><div class="php-messages"><?php foreach($messages as $message): ?><article class="php-message <?= e($message['direction']) ?>"><p><?= nl2br(e($message['body'])) ?></p><?php if($message['media_id']): ?><a href="/manage/whatsapp/messages/<?= e($message['id']) ?>/media/">View attachment</a><?php endif; ?><small><?= e($message['occurred_at'].' · '.$message['status']) ?></small></article><?php endforeach; ?></div><?php if($conversation['last_inbound_at']&&strtotime($conversation['last_inbound_at'])>time()-86400): ?><form method="post" action="reply/" class="o-form"><?= csrf() ?><input name="token" type="hidden" value="<?= e($token) ?>"><label class="o-field">Reply<textarea name="body" required maxlength="1024"></textarea></label><button class="o-btn o-btn-primary">Queue reply</button></form><?php else: ?><p>The 24-hour reply window is closed. Send an approved template through your automation.</p><?php endif; ?><?php else: ?><p>Choose a conversation to read messages.</p><?php endif; ?></section></div>
